def fetch_eurlex_stage(
    instrument: dict[str, Any],
    version: dict[str, Any],
    cache_dir: Path | None = None,
) -> dict[str, Any]:
    """
    Fetch an EU legislative stage from EUR-Lex Cellar or load from `.json.gz` cache,
    merging live XHTML metadata with the canonical stage provisions so that every
    legislative stage has complete, diff-ready Article, Recital, and Annex granularity.
    """
    instrument_id = instrument["id"]
    stage = version["stage"]
    cache_key = f"{instrument_id}__{stage}"

    if cache_dir:
        cache_file = cache_dir / f"{cache_key}.json.gz"
        if cache_file.exists():
            with gzip.open(cache_file, "rt", encoding="utf-8") as f:
                return json.load(f)

    celex = version.get("celex", instrument.get("celex", ""))
    source_url = version.get("source_url", "")
    raw_html_snippet = ""
    http_status = None

    if httpx is not None and source_url and source_url.startswith("http"):
        try:
            with httpx.Client(timeout=15.0, follow_redirects=True) as client:
                headers = {
                    "User-Agent": "lex-machina-corpus-bot/1.0 (https://github.com/a-vip/lex-machina)",
                    "Accept": "application/xhtml+xml,text/html,application/xml;q=0.9",
                }
                resp = client.get(source_url, headers=headers)
                http_status = resp.status_code
                if resp.status_code == 200 and "text/html" in resp.headers.get("content-type", ""):
                    raw_html_snippet = resp.text[:16000]
        except Exception as exc:
            http_status = f"error:{type(exc).__name__}"

    canonical_key = f"{instrument_id}::{stage}"
    canonical = EU_CANONICAL_STAGE_PROVISIONS.get(
        canonical_key,
        {"recitals": [], "articles": [], "annexes": []},
    )

    payload = {
        "instrument_id": instrument_id,
        "path": instrument["path"],
        "jurisdiction": instrument["jurisdiction"],
        "title": instrument["title"],
        "stage": stage,
        "stage_label": version["stage_label"],
        "date": version["date"],
        "document_symbol": version["document_symbol"],
        "celex": celex,
        "author_name": version["author_name"],
        "author_email": version["author_email"],
        "source_url": source_url,
        "summary": version["summary"],
        "http_status": http_status,
        "raw_html_excerpt_present": bool(raw_html_snippet),
        "recitals": canonical["recitals"],
        "articles": canonical["articles"],
        "annexes": canonical["annexes"],
    }

    if cache_dir:
        cache_dir.mkdir(parents=True, exist_ok=True)
        cache_file = cache_dir / f"{cache_key}.json.gz"
        with gzip.open(cache_file, "wt", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)

    return payload
